import React, { createContext, useState, useContext, useEffect, useCallback, useMemo } from 'react';
import { toast } from 'react-toastify';

const CartContext = createContext();

export const useCart = () => {
    const context = useContext(CartContext);
    if (!context) {
        throw new Error('useCart must be used within CartProvider');
    }
    return context;
};

export const CartProvider = ({ children }) => {
    const [cartItems, setCartItems] = useState([]);
    const [orderType, setOrderType] = useState('dine-in'); // dine-in, pickup
    const [orderNumber, setOrderNumber] = useState(null);

    const generateOrderNumber = useCallback(() => {
        const num = Math.floor(Math.random() * 9000) + 1000;
        setOrderNumber(num);
    }, []);

    useEffect(() => {
        // Generate order number when cart is initialized or cleared
        if (cartItems.length === 0 && !orderNumber) {
            generateOrderNumber();
        }
    }, [cartItems.length, orderNumber, generateOrderNumber]);

    const addToCart = useCallback((item) => {
        setCartItems(prevItems => {
            const existingItem = prevItems.find(i => i._id === item._id);
            
            if (existingItem) {
                return prevItems.map(i =>
                    i._id === item._id ? { ...i, quantity: i.quantity + 1 } : i
                );
            } else {
                return [...prevItems, { ...item, quantity: 1 }];
            }
        });
    }, []);

    const removeFromCart = useCallback((itemId) => {
        setCartItems(prevItems => prevItems.filter(i => i._id !== itemId));
        toast.info('Item removed from cart');
    }, []);

    const updateQuantity = useCallback((itemId, quantity) => {
        if (quantity <= 0) {
            removeFromCart(itemId);
            return;
        }
        setCartItems(prevItems => prevItems.map(i =>
            i._id === itemId ? { ...i, quantity } : i
        ));
    }, [removeFromCart]);

    const incrementQuantity = useCallback((itemId) => {
        setCartItems(prevItems => prevItems.map(i =>
            i._id === itemId ? { ...i, quantity: i.quantity + 1 } : i
        ));
    }, []);

    const decrementQuantity = useCallback((itemId) => {
        setCartItems(prevItems => {
            const item = prevItems.find(i => i._id === itemId);
            if (item.quantity > 1) {
                return prevItems.map(i =>
                    i._id === itemId ? { ...i, quantity: i.quantity - 1 } : i
                );
            } else {
                return prevItems.filter(i => i._id !== itemId);
            }
        });
    }, []);

    const clearCart = useCallback(() => {
        setCartItems([]);
        generateOrderNumber();
        toast.info('Cart cleared');
    }, [generateOrderNumber]);

    const getSubtotal = useCallback(() => {
        return cartItems.reduce((total, item) => total + (item.basePrice * item.quantity), 0);
    }, [cartItems]);

    const getParcelCharges = useCallback(() => {
        if (orderType === 'pickup') {
            return cartItems.reduce((total, item) => total + ((item.parcelCharges || 0) * item.quantity), 0);
        }
        return 0;
    }, [orderType, cartItems]);

    const getTax = useCallback(() => {
        return (getSubtotal() + getParcelCharges()) * 0.05; // 5% tax (CGST/SGST)
    }, [getSubtotal, getParcelCharges]);

    const getTotal = useCallback(() => {
        return getSubtotal() + getParcelCharges() + getTax();
    }, [getSubtotal, getParcelCharges, getTax]);

    const value = useMemo(() => ({
        cartItems,
        orderType,
        orderNumber,
        setOrderType,
        addToCart,
        removeFromCart,
        updateQuantity,
        incrementQuantity,
        decrementQuantity,
        clearCart,
        getSubtotal,
        getParcelCharges,
        getTax,
        getTotal
    }), [
        cartItems,
        orderType,
        orderNumber,
        addToCart,
        removeFromCart,
        updateQuantity,
        incrementQuantity,
        decrementQuantity,
        clearCart,
        getSubtotal,
        getParcelCharges,
        getTax,
        getTotal
    ]);

    return <CartContext.Provider value={value}>{children}</CartContext.Provider>;
};
