import React, { useState, useMemo } from 'react';
import { useCart } from '../context/CartContext';
import { toast } from 'react-toastify';

const CartPanel = () => {
    const {
        cartItems,
        orderType,
        orderNumber,
        setOrderType,
        incrementQuantity,
        decrementQuantity,
        clearCart,
        getSubtotal,
        getParcelCharges,
        getTax,
        getTotal,
    } = useCart();

    const [paymentMethod, setPaymentMethod] = useState('cash');
    const [showCustomerForm, setShowCustomerForm] = useState(false);
    const [customerDetails, setCustomerDetails] = useState({
        fullName: '',
        mobileNumber: '',
        email: '',
    });
    const [couponCode, setCouponCode] = useState('');
    const [appliedCoupon, setAppliedCoupon] = useState(null);
    const [couponLoading, setCouponLoading] = useState(false);

    // Memoize store and APIs to prevent re-creation on every render
    const { store } = useMemo(() => {
        return require('../context/AuthContext').useAuth();
    }, []);
    
    const { ordersAPI, billsAPI, kotAPI, couponsAPI } = useMemo(() => {
        return require('../services/api');
    }, []);

    // Apply coupon
    const handleApplyCoupon = async () => {
        if (!couponCode.trim()) {
            toast.error('Please enter a coupon code');
            return;
        }

        setCouponLoading(true);
        try {
            const response = await couponsAPI.validate({
                code: couponCode.trim(),
                orderAmount: getTotal(),
                storeId: store?.id || store?._id
            });

            if (response.data.success) {
                setAppliedCoupon(response.data.data);
                toast.success(`Coupon applied! You saved ₹${response.data.data.discount}`);
            }
        } catch (error) {
            const message = error.response?.data?.message || 'Invalid coupon code';
            toast.error(message);
        } finally {
            setCouponLoading(false);
        }
    };

    // Remove coupon
    const handleRemoveCoupon = () => {
        setAppliedCoupon(null);
        setCouponCode('');
        toast.info('Coupon removed');
    };

    // Calculate final total with discount
    const getFinalTotal = () => {
        const baseTotal = getTotal();
        if (appliedCoupon) {
            return baseTotal - appliedCoupon.discount;
        }
        return baseTotal;
    };

    // Helper function to open PDF in new tab with browser's native print dialog
    const openPDFInNewTab = (blob, filename) => {
        try {
            const url = window.URL.createObjectURL(blob);
            const newWindow = window.open(url, '_blank');
            
            if (newWindow) {
                // Set the title of the new window
                newWindow.document.title = filename;
                
                // Optional: Auto-trigger print dialog after a short delay
                setTimeout(() => {
                    newWindow.print();
                }, 500);
            } else {
                // Fallback if popup was blocked - download instead
                const link = document.createElement('a');
                link.href = url;
                link.download = filename;
                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);
                // Removed toast to avoid duplicate notifications
            }
            
            // Clean up after some time
            setTimeout(() => window.URL.revokeObjectURL(url), 10000);
        } catch (error) {
            console.error('Error opening PDF:', error);
            // Removed toast - error will be caught by parent function
        }
    };

    const handleSaveAndPrint = async () => {
        if (cartItems.length === 0) {
            toast.error('Cart is empty!');
            return;
        }

        try {
            // 1. Create Order with all details in ONE API call
            const orderPayload = {
                storeId: store?.id || store?._id,
                orderType,
                items: cartItems.map(item => ({
                    itemId: item._id,
                    itemType: 'FoodItemMaster',
                    itemName: item.itemName,
                    basePrice: item.basePrice,
                    quantity: item.quantity,
                    itemTotal: item.basePrice * item.quantity,
                    imageUrl: item.image,
                    gstPercent: 5,
                })),
                pricing: {
                    subtotal: getSubtotal(),
                    parcelCharges: getParcelCharges(),
                    totalTax: getTax(),
                    discount: appliedCoupon?.discount || 0,
                    grandTotal: getFinalTotal(),
                },
                payment: {
                    method: paymentMethod === 'cash' ? 'cod' : 'online',
                    status: paymentMethod === 'cash' ? 'pending' : 'paid',
                    totalAmount: getFinalTotal(),
                    paidAmount: paymentMethod === 'cash' ? 0 : getFinalTotal(),
                    pendingAmount: paymentMethod === 'cash' ? getFinalTotal() : 0,
                    transactionIds: [],
                },
                // Include coupon if applied
                ...(appliedCoupon && {
                    coupon: {
                        code: appliedCoupon.code,
                        couponId: appliedCoupon.couponId,
                        discount: appliedCoupon.discount
                    }
                }),
                // Include customer details if provided
                ...(showCustomerForm && (customerDetails.fullName || customerDetails.mobileNumber) && {
                    customerDetails: {
                        fullName: customerDetails.fullName,
                        mobileNumber: customerDetails.mobileNumber,
                        email: customerDetails.email,
                    }
                }),
            };

            const orderRes = await ordersAPI.create(orderPayload);
            
            // Validate response
            if (!(orderRes.data && (orderRes.data.success === true || orderRes.status === 201))) {
                throw new Error(orderRes.data?.message || 'Order creation failed');
            }
            
            const orderId = orderRes.data.order?._id;
            if (!orderId) {
                throw new Error('Order ID not found in response');
            }

            // 2. Generate BOTH Bill and KOT PDFs in parallel
            const [billResponse, kotResponse] = await Promise.all([
                billsAPI.print(orderId),
                kotAPI.print(orderId)
            ]);

            // Reset form
            clearCart();
            setCustomerDetails({ fullName: '', mobileNumber: '', email: '' });
            setAppliedCoupon(null);
            setCouponCode('');
            
            // Open both PDFs in new tabs
            const orderNum = orderRes.data.order.orderNumber;
            openPDFInNewTab(billResponse.data, `Bill-${orderNum}.pdf`);
            
            // Open KOT after a short delay to avoid popup blocking
            setTimeout(() => {
                openPDFInNewTab(kotResponse.data, `KOT-${orderNum}.pdf`);
            }, 300);

            toast.success('Order saved! PDFs opened in new tabs - use Ctrl+P to print or save');
        } catch (error) {
            console.error('Order creation error:', error);
            toast.error(error.message || 'Failed to create order');
        }
    };

    return (
        <aside className="w-[380px] bg-white dark:bg-slate-900 border-l border-slate-200 dark:border-slate-800 flex flex-col shrink-0">
            {/* Order Type Selection */}
            <div className="p-4 grid grid-cols-2 gap-2 shrink-0">
                <button
                    onClick={() => setOrderType('dine-in')}
                    className={`py-2.5 rounded-xl font-semibold flex flex-col items-center justify-center gap-1 transition-colors ${
                        orderType === 'dine-in'
                            ? 'bg-primary text-white shadow-md shadow-primary/20'
                            : 'bg-slate-100 dark:bg-slate-800 text-slate-500 hover:bg-slate-200 dark:hover:bg-slate-700'
                    }`}
                >
                    <span className="material-icons-round text-lg">restaurant</span>
                    <span className="text-[10px] uppercase">Dine In</span>
                </button>
                <button
                    onClick={() => setOrderType('pickup')}
                    className={`py-2.5 rounded-xl font-semibold flex flex-col items-center justify-center gap-1 transition-colors ${
                        orderType === 'pickup'
                            ? 'bg-primary text-white shadow-md shadow-primary/20'
                            : 'bg-slate-100 dark:bg-slate-800 text-slate-500 hover:bg-slate-200 dark:hover:bg-slate-700'
                    }`}
                >
                    <span className="material-icons-round text-lg">shopping_bag</span>
                    <span className="text-[10px] uppercase">Pickup</span>
                </button>
            </div>

            {/* Order Header */}
            <div className="px-4 pb-2 border-b border-slate-100 dark:border-slate-800 flex justify-between items-end shrink-0">
                <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">
                    Current Order #{orderNumber}
                </span>
                {cartItems.length > 0 && (
                    <button
                        onClick={clearCart}
                        className="text-primary text-xs font-bold flex items-center gap-1 hover:text-primary/80 transition-colors"
                    >
                        <span className="material-icons-round text-sm">delete_outline</span> CLEAR ALL
                    </button>
                )}
            </div>

            {/* Cart Items */}
            <div className="flex-1 overflow-y-auto px-4 py-2 space-y-4">
                {cartItems.length === 0 ? (
                    <div className="h-full flex flex-col items-center justify-center text-slate-400">
                        <span className="material-icons-round text-5xl mb-2">shopping_cart</span>
                        <p className="text-sm">No items in cart</p>
                    </div>
                ) : (
                    cartItems.map((item) => (
                        <div key={item._id} className="flex items-center gap-3">
                            <div className="w-12 h-12 rounded-lg bg-slate-100 dark:bg-slate-800 shrink-0 overflow-hidden">
                                {item.image ? (
                                    <img
                                        alt={item.itemName}
                                        className="w-full h-full object-cover"
                                        src={item.image}
                                    />
                                ) : (
                                    <div className="w-full h-full flex items-center justify-center">
                                        <span className="material-icons-round text-slate-400">
                                            restaurant
                                        </span>
                                    </div>
                                )}
                            </div>
                            <div className="flex-1">
                                <div className="flex justify-between">
                                    <h4 className="font-bold text-sm">{item.itemName}</h4>
                                    <span className="font-bold text-sm">
                                        ₹{(item.basePrice * item.quantity).toFixed(2)}
                                    </span>
                                </div>
                                <div className="flex items-center justify-between mt-2">
                                    <div className="flex items-center bg-slate-100 dark:bg-slate-800 rounded-lg p-1">
                                        <button
                                            onClick={() => decrementQuantity(item._id)}
                                            className="w-6 h-6 flex items-center justify-center text-slate-500 hover:text-primary"
                                        >
                                            <span className="material-icons-round text-sm">remove</span>
                                        </button>
                                        <span className="px-3 text-xs font-bold">{item.quantity}</span>
                                        <button
                                            onClick={() => incrementQuantity(item._id)}
                                            className="w-6 h-6 flex items-center justify-center text-slate-500 hover:text-primary"
                                        >
                                            <span className="material-icons-round text-sm">add</span>
                                        </button>
                                    </div>
                                    <span className="text-xs text-slate-400">
                                        Tax: ₹{(item.basePrice * item.quantity * 0.05).toFixed(2)}
                                    </span>
                                </div>
                            </div>
                        </div>
                    ))
                )}
            </div>

            {/* Billing Section */}
            {cartItems.length > 0 && (
                <div className="p-4 bg-slate-50 dark:bg-slate-800/50 border-t border-slate-200 dark:border-slate-800 shrink-0">
                    <div className="space-y-2 mb-4">
                        <div className="flex justify-between text-sm text-slate-500 dark:text-slate-400">
                            <span>Subtotal</span>
                            <span>₹{getSubtotal().toFixed(2)}</span>
                        </div>
                        {orderType === 'pickup' && getParcelCharges() > 0 && (
                            <div className="flex justify-between text-sm text-slate-500 dark:text-slate-400">
                                <span>Parcel Charges</span>
                                <span>₹{getParcelCharges().toFixed(2)}</span>
                            </div>
                        )}
                        <div className="flex justify-between text-sm text-slate-500 dark:text-slate-400">
                            <span>Tax (CGST/SGST 5%)</span>
                            <span>₹{getTax().toFixed(2)}</span>
                        </div>
                        
                        {/* Coupon Input */}
                        {!appliedCoupon ? (
                            <div className="pt-2">
                                <div className="flex gap-2">
                                    <input
                                        type="text"
                                        placeholder="Enter coupon code"
                                        value={couponCode}
                                        onChange={(e) => setCouponCode(e.target.value.toUpperCase())}
                                        onKeyPress={(e) => e.key === 'Enter' && handleApplyCoupon()}
                                        className="flex-1 px-3 py-2 text-sm rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 outline-none focus:ring-2 focus:ring-primary"
                                        disabled={couponLoading}
                                    />
                                    <button
                                        onClick={handleApplyCoupon}
                                        disabled={couponLoading || !couponCode.trim()}
                                        className="px-4 py-2 bg-primary text-white text-sm font-semibold rounded-lg hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                                    >
                                        {couponLoading ? 'Applying...' : 'Apply'}
                                    </button>
                                </div>
                            </div>
                        ) : (
                            <div className="flex justify-between items-center text-sm text-green-600 dark:text-green-400 pt-2">
                                <div className="flex items-center gap-2">
                                    <span className="material-icons-round text-base">local_offer</span>
                                    <span>Coupon ({appliedCoupon.code})</span>
                                </div>
                                <div className="flex items-center gap-2">
                                    <span>-₹{appliedCoupon.discount.toFixed(2)}</span>
                                    <button
                                        onClick={handleRemoveCoupon}
                                        className="text-red-500 hover:text-red-700"
                                    >
                                        <span className="material-icons-round text-base">close</span>
                                    </button>
                                </div>
                            </div>
                        )}
                        
                        <div className="flex justify-between items-center pt-2 border-t border-slate-200 dark:border-slate-700">
                            <span className="font-bold text-lg">Total</span>
                            <span className="font-bold text-2xl text-primary">
                                ₹{getFinalTotal().toFixed(2)}
                            </span>
                        </div>
                    </div>

                    {/* Customer Details (Optional) */}
                    <div className="mb-4">
                        <button
                            onClick={() => setShowCustomerForm(!showCustomerForm)}
                            className="w-full flex items-center justify-between p-3 rounded-xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors"
                        >
                            <div className="flex items-center gap-2">
                                <span className="material-icons-round text-slate-400">person</span>
                                <span className="text-sm font-semibold">Customer Details (Optional)</span>
                            </div>
                            <span className="material-icons-round text-slate-400">
                                {showCustomerForm ? 'expand_less' : 'expand_more'}
                            </span>
                        </button>
                        
                        {showCustomerForm && (
                            <div className="mt-2 space-y-2 p-3 bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-700">
                                <input
                                    type="text"
                                    placeholder="Customer Name"
                                    value={customerDetails.fullName}
                                    onChange={(e) => setCustomerDetails({ ...customerDetails, fullName: e.target.value })}
                                    className="w-full px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 text-sm outline-none focus:ring-2 focus:ring-primary"
                                />
                                <input
                                    type="tel"
                                    placeholder="Mobile Number"
                                    value={customerDetails.mobileNumber}
                                    onChange={(e) => setCustomerDetails({ ...customerDetails, mobileNumber: e.target.value })}
                                    className="w-full px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 text-sm outline-none focus:ring-2 focus:ring-primary"
                                />
                                <input
                                    type="email"
                                    placeholder="Email (Optional)"
                                    value={customerDetails.email}
                                    onChange={(e) => setCustomerDetails({ ...customerDetails, email: e.target.value })}
                                    className="w-full px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 text-sm outline-none focus:ring-2 focus:ring-primary"
                                />
                            </div>
                        )}
                    </div>

                    {/* Payment Method */}
                    <div className="grid grid-cols-2 gap-3 mb-4">
                        <button
                            onClick={() => setPaymentMethod('cash')}
                            className={`py-3 rounded-xl flex items-center justify-center gap-2 transition-colors ${
                                paymentMethod === 'cash'
                                    ? 'bg-primary text-white'
                                    : 'bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 hover:bg-slate-50'
                            }`}
                        >
                            <span className="material-icons-round text-slate-400">payments</span>
                            <span className="text-sm font-semibold">CASH</span>
                        </button>
                        <button
                            onClick={() => setPaymentMethod('card')}
                            className={`py-3 rounded-xl flex items-center justify-center gap-2 transition-colors ${
                                paymentMethod === 'card'
                                    ? 'bg-primary text-white'
                                    : 'bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 hover:bg-slate-50'
                            }`}
                        >
                            <span className="material-icons-round text-slate-400">credit_card</span>
                            <span className="text-sm font-semibold">CARD/UPI</span>
                        </button>
                    </div>

                    {/* Action Buttons */}
                    <div className="flex flex-col gap-3">
                        <button
                            onClick={handleSaveAndPrint}
                            className="w-full bg-primary text-white py-4 rounded-2xl font-bold text-lg flex items-center justify-center gap-3 shadow-xl shadow-primary/20 hover:bg-primary/90 active:scale-[0.98] transition-all uppercase tracking-wide"
                        >
                            <span className="material-icons-round">print</span>
                            SAVE &amp; PRINT BILL + KOT
                        </button>
                        <button
                            onClick={clearCart}
                            className="w-full bg-slate-200 dark:bg-slate-700 text-slate-700 dark:text-slate-200 py-2.5 rounded-xl font-bold text-xs uppercase hover:bg-slate-300 transition-colors"
                        >
                            Clear Cart
                        </button>
                    </div>
                </div>
            )}
        </aside>
    );
};

export default CartPanel;
