import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const Login = () => {
    const [storeCode, setStoreCode] = useState('');
    const [loading, setLoading] = useState(false);
    const { login } = useAuth();
    const navigate = useNavigate();

    const handleSubmit = async (e) => {
        e.preventDefault();
        
        if (!storeCode) {
            return;
        }

        setLoading(true);
        const result = await login(storeCode);
        
        if (result.success) {
            navigate('/');
        }
        setLoading(false);
    };

    return (
        <div className="h-screen bg-gradient-to-br from-background-light via-secondary/20 to-background-light flex items-center justify-center p-4">
            <div className="w-full max-w-md">
                <div className="bg-white dark:bg-slate-900 rounded-3xl shadow-2xl p-8 border border-slate-200 dark:border-slate-800">
                    <div className="text-center mb-8">
                        <img
                            alt="Bhakti Logo"
                            className="h-20 mx-auto mb-4"
                            src={`${process.env.PUBLIC_URL}/logo.png`}
                        />
                        <h1 className="text-3xl font-bold text-slate-900 dark:text-slate-100 mb-2">
                            Bhakti POS
                        </h1>
                        <p className="text-slate-500 dark:text-slate-400">
                            Point of Sale System
                        </p>
                    </div>

                    <form onSubmit={handleSubmit}>
                        <div className="mb-6">
                            <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">
                                Store Code
                            </label>
                            <input
                                type="text"
                                value={storeCode}
                                onChange={(e) => setStoreCode(e.target.value)}
                                className="w-full px-4 py-3 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100 text-center text-2xl font-bold tracking-widest focus:ring-2 focus:ring-primary focus:border-transparent outline-none transition-all"
                                placeholder="XXXX"
                                maxLength={6}
                                required
                            />
                        </div>

                        <button
                            type="submit"
                            disabled={loading || !storeCode}
                            className="w-full bg-primary text-white py-4 rounded-xl font-bold text-lg shadow-xl shadow-primary/20 hover:bg-primary/90 active:scale-[0.98] transition-all uppercase tracking-wide disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                        >
                            {loading ? (
                                <>
                                    <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                                    <span>Logging in...</span>
                                </>
                            ) : (
                                <>
                                    <span className="material-icons-round">login</span>
                                    <span>Login</span>
                                </>
                            )}
                        </button>
                    </form>

                    <div className="mt-6 text-center text-xs text-slate-400">
                        <p>Enter your store code to access POS</p>
                    </div>
                </div>

                <div className="mt-6 text-center text-xs text-slate-500">
                    <p>© 2026 Bhakti Food Stall. All rights reserved.</p>
                </div>
            </div>
        </div>
    );
};

export default Login;
