import React from 'react';

const FoodItemCard = ({ item, onAddToCart }) => {
    return (
        <div className="bg-white dark:bg-slate-900 rounded-xl p-3 border border-slate-200 dark:border-slate-800 hover:shadow-xl hover:border-primary/30 transition-all group flex flex-col cursor-pointer">
            {item.image && (
                <div className="w-full aspect-video bg-slate-100 dark:bg-slate-800 rounded-lg mb-3 overflow-hidden relative">
                    <img
                        alt=""
                        className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500"
                        src={item.image}
                        onError={(e) => { e.target.parentElement.style.display = 'none'; }}
                    />
                    <div className="absolute top-2 left-2 flex gap-2">
                        {item.isBestseller && (
                            <div className="bg-orange-500 text-white text-[10px] font-bold px-2 py-1 rounded-md">
                                BESTSELLER
                            </div>
                        )}
                        {item.isFavorite && (
                            <div className="bg-yellow-500 text-white p-1 rounded-md flex items-center justify-center">
                                <span className="material-icons-round text-sm">star</span>
                            </div>
                        )}
                    </div>
                </div>
            )}
            {!item.image && (
                <div className="flex gap-2 mb-2">
                    {item.isBestseller && (
                        <div className="bg-orange-500 text-white text-[10px] font-bold px-2 py-1 rounded-md">
                            BESTSELLER
                        </div>
                    )}
                    {item.isFavorite && (
                        <div className="bg-yellow-500 text-white p-1 rounded-md flex items-center justify-center">
                            <span className="material-icons-round text-sm">star</span>
                        </div>
                    )}
                </div>
            )}
            <div className="flex-1 flex flex-col">
                <div className="flex justify-between items-start mb-1">
                    <h3 className="font-bold text-base leading-tight">{item.itemName}</h3>
                    <span
                        className={`text-[10px] font-bold px-2 py-0.5 rounded-full uppercase shrink-0 ${
                            item.isVeg
                                ? 'bg-emerald-100 text-emerald-600'
                                : 'bg-red-100 text-red-600'
                        }`}
                    >
                        {item.isVeg ? 'VEG' : 'NON-VEG'}
                    </span>
                </div>
                {item.description && (
                    <p className="text-xs text-slate-500 dark:text-slate-400 mb-3 line-clamp-1">
                        {item.description}
                    </p>
                )}
                <div className="mt-auto flex items-center justify-between">
                    <span className="text-lg font-bold text-primary">
                        ₹{item.basePrice?.toFixed(2)}
                    </span>
                    <button
                        onClick={() => onAddToCart(item)}
                        className="bg-primary text-white w-9 h-9 rounded-lg flex items-center justify-center shadow-lg shadow-primary/20 hover:scale-105 active:scale-95 transition-all"
                    >
                        <span className="material-icons-round text-lg">add</span>
                    </button>
                </div>
            </div>
        </div>
    );
};

export default FoodItemCard;
